using System;using System.Collections.Generic;using System.Globalization;using System.Linq;using Avalonia;using Avalonia.Controls;using Avalonia.Layout;using Avalonia.Media;using Avalonia.Interactivity;using Kreta.Core;using Kreta.Contexts;public class FeladatNaptarView : IEvolView{    private IStudentContext? _context;    private Grid? _calendarGrid;    private TextBlock? _monthYearTextBlock;    private ListBox? _detailsListBox;    private TextBlock? _statusTextBlock;    private DateTime _displayedMonth;    private List<GenericRecord>? _allEvents;    private User? _currentUser;    private const string TestEntityType = "Test";    private const string HomeworkEntityType = "Homework";    public new string Name => "Feladat Naptár";    public string Description => "A közelgő dolgozatok és házi feladatok beadási határidejének megtekintése naptár formátumban.";    public FeladatNaptarView() { }    public FeladatNaptarView(IStudentContext context)    {        _context = context;    }    public Control CreateView()    {        _displayedMonth = DateTime.Today;        var mainPanel = new DockPanel();        var topPanel = new StackPanel        {            Orientation = Orientation.Horizontal,            HorizontalAlignment = HorizontalAlignment.Center,            Spacing = 10,            Margin = new Thickness(0, 0, 0, 10)        };        var prevButton = new Button { Content = "<" };        prevButton.Click += (s, e) => ChangeMonth(-1);        var nextButton = new Button { Content = ">" };        nextButton.Click += (s, e) => ChangeMonth(1);        _monthYearTextBlock = new TextBlock        {            VerticalAlignment = VerticalAlignment.Center,            FontWeight = FontWeight.Bold,            FontSize = 16        };        topPanel.Children.Add(prevButton);        topPanel.Children.Add(_monthYearTextBlock);        topPanel.Children.Add(nextButton);        DockPanel.SetDock(topPanel, Dock.Top);        _calendarGrid = new Grid        {            ShowGridLines = true,            Margin = new Thickness(10)        };        _detailsListBox = new ListBox        {            Margin = new Thickness(10),            Height = 150        };        DockPanel.SetDock(_detailsListBox, Dock.Bottom);        _statusTextBlock = new TextBlock        {            Margin = new Thickness(10, 5)        };        DockPanel.SetDock(_statusTextBlock, Dock.Bottom);        var calendarPanel = new StackPanel();        calendarPanel.Children.Add(_calendarGrid);        mainPanel.Children.Add(topPanel);        mainPanel.Children.Add(_statusTextBlock);        mainPanel.Children.Add(_detailsListBox);        mainPanel.Children.Add(calendarPanel);        LoadDataAndBuildCalendar();        return mainPanel;    }    private void LoadDataAndBuildCalendar()    {        if (_context == null || _statusTextBlock == null) return;        _statusTextBlock.Text = "Adatok betöltése...";        try        {            _currentUser = _context.GetMyProfile();            if (_currentUser == null)            {                _statusTextBlock.Text = "Felhasználói profil nem található.";                return;            }            var myTests = _context.QueryEntities(TestEntityType)                                  .Where(t => t.Data.ContainsKey("ClassName") && t.Data["ClassName"] == _currentUser.ClassName)                                  .ToList();            var myHomeworks = _context.QueryEntities(HomeworkEntityType)                                      .Where(h => h.Data.ContainsKey("ClassName") && h.Data["ClassName"] == _currentUser.ClassName)                                      .ToList();            _allEvents = myTests.Concat(myHomeworks).ToList();            _statusTextBlock.Text = !_allEvents.Any() ? "Nincsenek rögzített dolgozatok vagy házi feladatok." : "";        }        catch (Exception ex)        {            _statusTextBlock.Text = $"Hiba a betöltés során: {ex.Message}";            _allEvents = new List<GenericRecord>();        }        BuildCalendarGrid();    }    private void BuildCalendarGrid()    {        if (_calendarGrid == null || _monthYearTextBlock == null) return;        _monthYearTextBlock.Text = _displayedMonth.ToString("yyyy. MMMM", new CultureInfo("hu-HU"));        _calendarGrid.Children.Clear();        _calendarGrid.RowDefinitions.Clear();        _calendarGrid.ColumnDefinitions.Clear();        for (int i = 0; i < 7; i++)            _calendarGrid.ColumnDefinitions.Add(new ColumnDefinition(GridLength.Star));        string[] daysOfWeek = { "H", "K", "Sze", "Cs", "P", "Szo", "V" };        _calendarGrid.RowDefinitions.Add(new RowDefinition(GridLength.Auto));        for (int i = 0; i < 7; i++)        {            var header = new TextBlock { Text = daysOfWeek[i], HorizontalAlignment = HorizontalAlignment.Center, VerticalAlignment = VerticalAlignment.Center, FontWeight = FontWeight.Bold };            Grid.SetRow(header, 0);            Grid.SetColumn(header, i);            _calendarGrid.Children.Add(header);        }        var firstDayOfMonth = new DateTime(_displayedMonth.Year, _displayedMonth.Month, 1);        int daysInMonth = DateTime.DaysInMonth(_displayedMonth.Year, _displayedMonth.Month);        int dayOfWeek = ((int)firstDayOfMonth.DayOfWeek + 6) % 7;        int currentDay = 1;        int maxRows = (int)Math.Ceiling((dayOfWeek + daysInMonth) / 7.0);        for(int i = 1; i <= maxRows; i++)             _calendarGrid.RowDefinitions.Add(new RowDefinition(GridLength.Star));        for (int row = 1; row <= maxRows && currentDay <= daysInMonth; row++)        {            for (int col = (row == 1 ? dayOfWeek : 0); col < 7 && currentDay <= daysInMonth; col++)            {                var dayDate = new DateTime(_displayedMonth.Year, _displayedMonth.Month, currentDay);                var hasEvent = _allEvents?.Any(e => GetEventDate(e)?.Date == dayDate.Date) ?? false;                var dayButton = new Button                {                    Content = currentDay.ToString(), Tag = dayDate, HorizontalAlignment = HorizontalAlignment.Stretch, VerticalAlignment = VerticalAlignment.Stretch, MinHeight=40                };                if (hasEvent) { dayButton.FontWeight = FontWeight.Bold; dayButton.Background = Brushes.LightBlue; }                if (dayDate.Date == DateTime.Today) { dayButton.BorderBrush = Brushes.Red; dayButton.BorderThickness = new Thickness(2); }                dayButton.Click += Day_Click;                Grid.SetRow(dayButton, row); Grid.SetColumn(dayButton, col);                _calendarGrid.Children.Add(dayButton);                currentDay++;            }        }    }    private DateTime? GetEventDate(GenericRecord record)    {        string? dateStr = null;        if (record.EntityType == TestEntityType && record.Data.TryGetValue("Date", out dateStr)) { }        else if (record.EntityType == HomeworkEntityType && record.Data.TryGetValue("Deadline", out dateStr)) { }        if (dateStr != null && DateTime.TryParse(dateStr, CultureInfo.InvariantCulture, DateTimeStyles.None, out DateTime parsedDate))        {            return parsedDate;        }        return null;    }    private void Day_Click(object? sender, RoutedEventArgs e)    {        if (sender is not Button button || button.Tag is not DateTime selectedDate || _detailsListBox == null || _allEvents == null) return;        var eventsOnDay = _allEvents.Where(ev => GetEventDate(ev)?.Date == selectedDate.Date).ToList();        var displayItems = new List<string>();        foreach(var ev in eventsOnDay)        {            if (ev.EntityType == TestEntityType) displayItems.Add($"[Dolgozat] {ev.Data.GetValueOrDefault("SubjectName", "?")}: {ev.Data.GetValueOrDefault("Topic", "N/A")}");            else if (ev.EntityType == HomeworkEntityType) displayItems.Add($"[HF Határidő] {ev.Data.GetValueOrDefault("SubjectName", "?")}: {ev.Data.GetValueOrDefault("Description", "N/A")}");        }        _detailsListBox.ItemsSource = displayItems.Any() ? displayItems : new List<string> { "Nincs esemény ezen a napon." };    }    private void ChangeMonth(int monthDelta)    {        _displayedMonth = _displayedMonth.AddMonths(monthDelta);        BuildCalendarGrid();        if (_detailsListBox != null) _detailsListBox.ItemsSource = null;    }}